recipes.code:
{
  "inputs": [
    {
      "id": "deinai-mcp-token",
      "type": "promptString",
      "description": "MCP JWT from Deinai token API",
      "password": true
    }
  ],
  "servers": {
    "creator-skill": {
      "type": "stdio",
      "command": "uvx",
      "args": [
        "deinai-mcp@1.0.2"
      ],
      "env": {
        "DEINAI_MCP_TOKEN": "${input:deinai-mcp-token}",
        "DEINAI_MCP_URL": "<deinai-mcp-url>"
      }
    }
  }
}
